package ua.rozcinky.app;
import android.app.*;
import android.os.*;
import android.graphics.Color;
import android.widget.*;
import android.view.*;
import android.text.*;
import org.json.*;
import java.util.*;
import java.math.*;
public class MainActivity extends Activity {
 LinearLayout root; JSONArray jobs,clients,cart; android.content.SharedPreferences prefs;
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("data",0);jobs=load("jobs");if(!prefs.contains("jobs")){try(java.io.InputStream in=getAssets().open("jobs.json")){java.io.ByteArrayOutputStream o=new java.io.ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)o.write(buf,0,n);jobs=new JSONArray(o.toString("UTF-8"));}catch(Exception e){}}clients=load("clients");cart=load("cart");home();}
 JSONArray load(String k){try{return new JSONArray(prefs.getString(k,"[]"));}catch(Exception e){return new JSONArray();}}
 void save(){prefs.edit().putString("jobs",jobs.toString()).putString("clients",clients.toString()).putString("cart",cart.toString()).apply();}
 void screen(String title){ScrollView s=new ScrollView(this);s.setFillViewport(true);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(20,48,20,32);root.setBackgroundColor(0xff101e30);s.addView(root);setContentView(s);label(root,title,26);}
 void label(LinearLayout l,String t,int size){TextView v=new TextView(this);v.setText(t);v.setTextColor(Color.WHITE);v.setTextSize(size);v.setPadding(8,12,8,12);l.addView(v);}
 void btn(LinearLayout l,String t,Runnable r){Button b=new Button(this);b.setText(t);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff254567));l.addView(b);b.setOnClickListener(v->r.run());}
 EditText field(LinearLayout l,String hint){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);l.addView(e);return e;}
 void home(){screen("РОЗЦІНКИ");btn(root,"⚡ Розцінки на електрику",()->catalog(0));btn(root,"🔧 Розцінки на сантехніку",()->catalog(1));btn(root,"База клієнтів",()->people());btn(root,"Вибрані роботи / звіти",()->reports());label(root,"Версія 1.0.0",14);}
 void catalog(int cat){screen(cat==0?"Електрика":"Сантехніка");btn(root,"Назад",()->home());btn(root,"Додати роботу",()->editJob(cat));EditText search=field(root,"Пошук роботи");LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);Runnable refresh=()->{list.removeAllViews();for(int i=0;i<jobs.length();i++){JSONObject j=jobs.optJSONObject(i);if(j==null||j.optInt("cat")!=cat||!j.optString("name").toLowerCase(Locale.ROOT).contains(search.getText().toString().toLowerCase(Locale.ROOT)))continue;btn(list,j.optString("name")+" • "+(j.optString("price").isEmpty()?"Договірна":j.optString("priceType")+" "+j.optString("price")+" грн")+" / "+j.optString("unit"),()->choose(j,cat));}};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){refresh.run();}public void afterTextChanged(Editable e){}});refresh.run();}
 void editJob(int cat){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText n=field(l,"Назва роботи"),u=field(l,"Одиниця вимірювання"),p=field(l,"Ціна або порожньо");new AlertDialog.Builder(this).setTitle("Нова робота").setView(l).setNegativeButton("Скасувати",null).setPositiveButton("Зберегти",(d,w)->{if(n.length()==0||u.length()==0)return;try{JSONObject j=new JSONObject();j.put("cat",cat);j.put("name",n.getText());j.put("unit",u.getText());j.put("price",p.getText().toString());jobs.put(j);save();catalog(cat);}catch(Exception e){}}).show();}
 void choose(JSONObject j,int cat){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText q=field(l,"Кількість"),p=field(l,"Ціна грн");q.setText("1");p.setText(j.optString("price"));new AlertDialog.Builder(this).setTitle(j.optString("name")).setView(l).setNegativeButton("Скасувати",null).setPositiveButton("Додати",(d,w)->{try{BigDecimal a=new BigDecimal(q.getText().toString().replace(',','.')),b=new BigDecimal(p.getText().toString().replace(',','.'));if(a.signum()<=0||b.signum()<0)throw new Exception();JSONObject row=new JSONObject(j.toString());row.put("qty",a.toPlainString());row.put("price",b.toPlainString());cart.put(row);save();Toast.makeText(this,"Додано",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Перевірте кількість і ціну",Toast.LENGTH_LONG).show();}}).show();}
 void people(){screen("База клієнтів");btn(root,"Назад",()->home());btn(root,"Додати клієнта",()->{LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText n=field(l,"ПІБ"),p=field(l,"Телефон"),a=field(l,"Адреса");new AlertDialog.Builder(this).setTitle("Клієнт").setView(l).setNegativeButton("Скасувати",null).setPositiveButton("Зберегти",(d,w)->{if(n.length()==0)return;try{JSONObject c=new JSONObject();c.put("name",n.getText().toString());c.put("phone",p.getText().toString());c.put("address",a.getText().toString());clients.put(c);save();people();}catch(Exception e){}}).show();});for(int i=0;i<clients.length();i++){JSONObject c=clients.optJSONObject(i);label(root,c.optString("name")+"\n"+c.optString("phone")+"\n"+c.optString("address"),17);}}
 void reports(){screen("Формування звітів");btn(root,"Назад",()->home());btn(root,"Електричний звіт",()->report(0));btn(root,"Сантехнічний звіт",()->report(1));btn(root,"Об'єднаний звіт",()->report(2));}
 void report(int cat){screen(cat==0?"Електричний звіт":cat==1?"Сантехнічний звіт":"Об'єднаний звіт");btn(root,"Назад",()->reports());BigDecimal total=BigDecimal.ZERO;for(int i=0;i<cart.length();i++){JSONObject j=cart.optJSONObject(i);if(cat!=2&&j.optInt("cat")!=cat)continue;BigDecimal sum=new BigDecimal(j.optString("qty")).multiply(new BigDecimal(j.optString("price")));total=total.add(sum);label(root,j.optString("name")+"\n"+j.optString("qty")+" "+j.optString("unit")+" × "+j.optString("price")+" = "+sum.setScale(2,RoundingMode.HALF_UP)+" грн",16);}label(root,"Разом: "+total.setScale(2,RoundingMode.HALF_UP)+" грн",24);btn(root,"Зберегти PDF",()->selectClient(cat));}
 void selectClient(int cat){String[] names=new String[clients.length()+1];names[0]="Без клієнта";for(int i=0;i<clients.length();i++)names[i+1]=clients.optJSONObject(i).optString("name");new AlertDialog.Builder(this).setTitle("Виберіть клієнта").setItems(names,(d,w)->exportPdf(cat,w==0?null:clients.optJSONObject(w-1))).show();}
 byte[] pendingPdf;
 void exportPdf(int cat,JSONObject client){try{android.graphics.pdf.PdfDocument pdf=new android.graphics.pdf.PdfDocument();android.graphics.Paint p=new android.graphics.Paint(3);p.setTextSize(12);ArrayList<String> lines=new ArrayList<>();lines.add(cat==0?"Електричний звіт":cat==1?"Сантехнічний звіт":"Об'єднаний звіт");lines.add(new java.text.SimpleDateFormat("dd.MM.yyyy HH:mm",Locale.ROOT).format(new Date()));if(client!=null){lines.add("Клієнт: "+client.optString("name"));lines.add("Телефон: "+client.optString("phone"));lines.add("Адреса: "+client.optString("address"));}BigDecimal total=BigDecimal.ZERO;for(int group=0;group<2;group++){if(cat!=2&&cat!=group)continue;lines.add(group==0?"ЕЛЕКТРИКА":"САНТЕХНІКА");BigDecimal subtotal=BigDecimal.ZERO;for(int i=0;i<cart.length();i++){JSONObject j=cart.optJSONObject(i);if(j.optInt("cat")!=group)continue;BigDecimal sum=new BigDecimal(j.optString("qty")).multiply(new BigDecimal(j.optString("price")));subtotal=subtotal.add(sum);lines.add(j.optString("name"));lines.add(j.optString("qty")+" "+j.optString("unit")+" × "+j.optString("price")+" = "+sum.setScale(2,RoundingMode.HALF_UP)+" грн");}total=total.add(subtotal);lines.add("Підсумок: "+subtotal.setScale(2,RoundingMode.HALF_UP)+" грн");}lines.add("ЗАГАЛОМ: "+total.setScale(2,RoundingMode.HALF_UP)+" грн");int pageNo=1,y=50;android.graphics.pdf.PdfDocument.Page page=pdf.startPage(new android.graphics.pdf.PdfDocument.PageInfo.Builder(595,842,pageNo).create());for(String line:lines){String rest=line;do{int count=Math.max(1,p.breakText(rest,true,515,null));count=Math.min(count,rest.length());if(y>790){pdf.finishPage(page);page=pdf.startPage(new android.graphics.pdf.PdfDocument.PageInfo.Builder(595,842,++pageNo).create());y=50;}page.getCanvas().drawText(rest.substring(0,count),40,y,p);y+=20;rest=rest.substring(count);}while(!rest.isEmpty());}pdf.finishPage(page);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();pdf.writeTo(out);pdf.close();pendingPdf=out.toByteArray();android.content.Intent intent=new android.content.Intent(android.content.Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(android.content.Intent.CATEGORY_OPENABLE);intent.setType("application/pdf");intent.putExtra(android.content.Intent.EXTRA_TITLE,"Rozcinky-"+System.currentTimeMillis()+".pdf");startActivityForResult(intent,41);}catch(Exception e){Toast.makeText(this,"Помилка створення PDF",Toast.LENGTH_LONG).show();}}
 @Override protected void onActivityResult(int request,int result,android.content.Intent data){super.onActivityResult(request,result,data);if(request==41&&result==RESULT_OK&&data!=null&&pendingPdf!=null){try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new java.io.IOException();out.write(pendingPdf);Toast.makeText(this,"PDF збережено",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Помилка збереження",Toast.LENGTH_LONG).show();}finally{pendingPdf=null;}}}
}
